import subprocess, sys, os, difflib

def run(args, check=True):
    p = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and p.returncode != 0:
        sys.stderr.buffer.write(p.stderr)
        raise SystemExit(p.returncode)
    return p

def blob(rev, path):
    p = run(['git', 'show', f'{rev}:{path}'], check=False)
    if p.returncode != 0:
        return None
    return p.stdout

def split_lines(data):
    return data.splitlines(keepends=True)

def map_position(pos, base, ours):
    sm = difflib.SequenceMatcher(None, base, ours, autojunk=False)
    blocks = sm.get_matching_blocks()
    for a, b, size in blocks:
        if size == 0:
            continue
        if a <= pos < a + size:
            return b + (pos - a)
        if a == pos:
            return b
    for a, b, size in blocks:
        if size and a > pos:
            return b
    return len(ours)

def apply_upstream_insertions(base, ours, theirs):
    sm = difflib.SequenceMatcher(None, base, theirs, autojunk=False)
    insertions = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag != 'insert':
            continue
        new = [line for line in theirs[j1:j2] if line not in ours]
        if new:
            insertions.append((map_position(i1, base, ours), new))
    result = list(ours)
    for pos, new in sorted(insertions, key=lambda item: item[0], reverse=True):
        result[pos:pos] = new
    return b''.join(result)

def resolve_markers(data):
    lines = split_lines(data)
    out = []
    i = 0
    while i < len(lines):
        if lines[i].startswith(b'<<<<<<<'):
            i += 1
            ours = []
            while i < len(lines) and not lines[i].startswith(b'|||||||') and not lines[i].startswith(b'======='):
                ours.append(lines[i])
                i += 1
            base = []
            if i < len(lines) and lines[i].startswith(b'|||||||'):
                i += 1
                while i < len(lines) and not lines[i].startswith(b'======='):
                    base.append(lines[i])
                    i += 1
            if i < len(lines) and lines[i].startswith(b'======='):
                i += 1
            theirs = []
            while i < len(lines) and not lines[i].startswith(b'>>>>>>>'):
                theirs.append(lines[i])
                i += 1
            if i < len(lines) and lines[i].startswith(b'>>>>>>>'):
                i += 1
            out.append(apply_upstream_insertions(base, ours, theirs))
        else:
            out.append(lines[i])
            i += 1
    return b''.join(out)

def write_file(path, data):
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(path, 'wb') as f:
        f.write(data)

conflicts = run(['git', 'diff', '--name-only', '--diff-filter=U', '-z']).stdout.split(b'\0')
for raw_path in conflicts:
    if not raw_path:
        continue
    path = os.fsdecode(raw_path)
    ours = blob('HEAD', path)
    theirs = blob('MERGE_HEAD', path)
    if ours is None:
        run(['git', 'rm', '-f', '--', path], check=False)
        continue
    if theirs is None:
        write_file(path, ours)
        run(['git', 'add', '--', path])
        continue
    if b'\0' in ours or b'\0' in theirs:
        write_file(path, ours)
        run(['git', 'add', '--', path])
        continue
    run(['git', 'checkout', '--conflict=diff3', '--', path], check=False)
    if os.path.exists(path):
        with open(path, 'rb') as f:
            conflicted = f.read()
        resolved = resolve_markers(conflicted)
    else:
        resolved = ours
    write_file(path, resolved)
    run(['git', 'add', '--', path])
